"""European business positioning and the public enterprise homepage."""
from html import escape as esc
TEXT={
'en':dict(title='AI systems, custom CRM & IT for Europe | Marleo',desc='Custom AI systems, CRM software and IT engineering for European organisations. Connect your operations, business data and teams with Marleo.',kicker='AI, CRM & IT ENGINEERING · EUROPE',hero=['Your next stage.','Built on better systems.'],lead='Custom AI systems, CRM platforms and connected IT for European organisations. We turn complex operations into software your teams can work with.',cta='Discuss your project',secondary='Explore our approach',note='From a focused pilot to a broader implementation. Scope, responsibilities and acceptance criteria agreed from the start.',stage='One connected operation',stageNote='Illustrative system architecture · not a live customer environment',inbox='Business information',inputs=['Documents & requests','CRM & ERP records','Approved knowledge'],core='Marleo',coreSub='Your processes, connected.',review='Access. Review. Control.',outputs=['AI-assisted workflows','Custom CRM & portals','Operational dashboards'],end='People & business systems',pillars='WHAT WE BUILD',pillarsTitle='The systems behind your next move.',services=[('AI systems & automation','Connect company knowledge, process documents and prepare actions with clear review points. Start with one workflow, then expand against agreed results.','ai-infrastructuur','Explore AI systems','Document processing · Knowledge · Workflow agents'),('Custom CRM & business software','Bring customer information, commercial processes, portals and reporting into one application designed around your organisation.','solutions/custom-crm','Explore custom CRM','Customer operations · Integrations · Management dashboards'),('IT, cloud & security','Give your software a practical foundation: managed IT, cloud services, access controls and support with clearly agreed responsibilities.','managed-it','Explore IT services','Microsoft 365 · Infrastructure · Access & continuity')],scope='EUROPEAN SCOPE. CLEAR DELIVERY.',scopeTitle=['Built for your organisation.','Ready for the wider picture.'],scopeBody='A single department and a multi-team organisation need different things. We define the people, systems, data boundaries and handovers around your project before building.',scopeItems=[('Across teams','Connect operations, sales and technical stakeholders around one agreed process.'),('Data & deployment','Agree processing locations, hosting options, external providers and access before implementation.'),('A clear handover','Define testing, documentation, ownership and ongoing support in the project agreement.')],security='Explore security & deployment',process='HOW WE WORK',processTitle='From first question to everyday use.',steps=[('Discover','Understand the process, existing tools, data and constraints.'),('Design','Agree the architecture, scope, budget and acceptance criteria.'),('Build & validate','Deliver a focused application and test representative scenarios.'),('Operate & evolve','Agree rollout, handover, monitoring and the next improvements.')],faqTitle='Questions before an enterprise project.',faq=[('Do you work with larger European organisations?','Our project approach can be scoped for a department, a growing company or a larger organisation. We agree the required stakeholders, procurement steps, integrations, security requirements and delivery responsibilities during discovery.'),('Can you connect our existing CRM or ERP?','We assess available APIs, permissions, data quality and vendor constraints first. The implementation can connect existing software, extend a workflow or introduce a custom CRM where that makes sense.'),('Can we choose where our data is processed?','Hosting locations, AI providers, access and retention are project decisions. We assess the requested European hosting or private deployment requirements before proposing an architecture. We define the required controls and responsibilities in the project scope.'),('Do you still build websites?','Yes. Websites, online stores and branding remain available. Website projects are collected in Work, separately from the AI, CRM and IT focus of this homepage.')],work='View website work',crmTitle='Custom CRM software for European organisations',crmDesc='Custom CRM development for European businesses: customer operations, portals, integrations and reporting, scoped around your workflows.',crmLead='A CRM should reflect how your organisation works. We design customer platforms around your teams, data and commercial processes, with a clear plan for migration, integration and support.',crmSections=[('Map the customer lifecycle','Define enquiries, relationships, opportunities, quotes, orders and handovers with the teams that use them.'),('Connect the tools you already use','Assess email, websites, finance and ERP interfaces. Confirm the available APIs, permissions and synchronisation rules before development.'),('Design access and reporting','Scope user roles, customer portals, management views and the definitions behind operational reports.'),('Plan implementation and ownership','Agree data migration, representative tests, rollout, documentation, source code arrangements and ongoing support.')],crmFaq=[('When is a custom CRM appropriate?','When existing tools cannot reasonably support your workflow, integration or access requirements. Discovery compares extending your current software with building a custom application.'),('Can AI be part of the CRM?','Yes, for agreed tasks such as structuring enquiries or preparing responses from approved information. Prices, commitments and consequential actions can remain subject to human approval.'),('How much does a custom CRM cost?','The scope, integrations, migration, access model and support requirements determine the proposal. We agree deliverables, acceptance criteria and recurring costs before development.')]),
'nl':dict(title='AI-systemen, CRM op maat & IT in Europa | Marleo',desc='AI-systemen, CRM-software op maat en IT-engineering voor Europese organisaties. Verbind processen, bedrijfsgegevens en teams met Marleo.',kicker='AI, CRM & IT-ENGINEERING · EUROPA',hero=['Een volgende stap.','Een sterker systeem.'],lead='AI-systemen, CRM-platformen op maat en verbonden IT voor Europese organisaties. We vertalen complexe processen naar software waarmee je teams verder kunnen.',cta='Bespreek je project',secondary='Ontdek onze aanpak',note='Van een gerichte pilot tot een bredere implementatie. Scope, verantwoordelijkheden en acceptatiecriteria liggen vooraf vast.',stage='Eén verbonden organisatie',stageNote='Illustratieve systeemarchitectuur · geen live klantomgeving',inbox='Bedrijfsinformatie',inputs=['Documenten & aanvragen','CRM- & ERP-gegevens','Goedgekeurde kennis'],core='Marleo',coreSub='Je processen, verbonden.',review='Toegang. Controle. Goedkeuring.',outputs=['AI-ondersteunde workflows','CRM & portalen op maat','Operationele dashboards'],end='Mensen & bedrijfssystemen',pillars='WAT WE BOUWEN',pillarsTitle='De systemen achter je volgende stap.',services=[('AI-systemen & automatisering','Verbind bedrijfskennis, verwerk documenten en bereid acties voor met duidelijke controlemomenten. Begin bij één proces en breid uit op basis van afgesproken resultaten.','ai-infrastructuur','Ontdek AI-systemen','Documentverwerking · Kennis · Workflowagents'),('CRM & bedrijfssoftware op maat','Breng klantinformatie, commerciële processen, portalen en rapportage samen in een toepassing die past bij je organisatie.','solutions/custom-crm','Ontdek CRM op maat','Klantprocessen · Integraties · Managementdashboards'),('IT, cloud & security','Een praktische basis voor je software: IT-beheer, cloud, toegangscontrole en ondersteuning met duidelijke verantwoordelijkheden.','managed-it','Ontdek IT-diensten','Microsoft 365 · Infrastructuur · Toegang & continuïteit')],scope='EUROPEES BEREIK. DUIDELIJKE OPLEVERING.',scopeTitle=['Gebouwd voor je organisatie.','Met oog voor het geheel.'],scopeBody='Een afdeling en een organisatie met meerdere teams hebben andere behoeften. We brengen mensen, systemen, gegevensgrenzen en overdracht in kaart vóór we bouwen.',scopeItems=[('Over teams heen','Verbind operations, verkoop en technische betrokkenen rond één afgesproken proces.'),('Gegevens & implementatie','Leg verwerkingslocaties, hostingkeuzes, leveranciers en toegangsrechten vooraf vast.'),('Een duidelijke overdracht','Spreek testen, documentatie, eigendom en ondersteuning af in de projectovereenkomst.')],security='Bekijk security & implementatie',process='ONZE AANPAK',processTitle='Van eerste vraag tot dagelijks gebruik.',steps=[('Onderzoeken','Breng het proces, de bestaande tools, gegevens en beperkingen in kaart.'),('Ontwerpen','Spreek architectuur, scope, begroting en acceptatiecriteria af.'),('Bouwen & toetsen','Lever een gerichte toepassing en test representatieve situaties.'),('Beheren & verbeteren','Leg uitrol, overdracht, monitoring en verdere verbeteringen vast.')],faqTitle='Vragen vóór een groter IT-project.',faq=[('Werken jullie ook voor grotere Europese organisaties?','Onze projectaanpak kan worden afgestemd op een afdeling, groeibedrijf of grotere organisatie. Tijdens de analyse leggen we betrokkenen, aankoopprocedures, integraties, beveiligingseisen en verantwoordelijkheden vast.'),('Kunnen jullie ons huidige CRM of ERP verbinden?','We onderzoeken eerst beschikbare API’s, toegangsrechten, gegevenskwaliteit en beperkingen van leveranciers. Daarna bepalen we of we bestaande software verbinden, een proces uitbreiden of CRM op maat ontwikkelen.'),('Kunnen we kiezen waar onze gegevens verwerkt worden?','Hostinglocaties, AI-leveranciers, toegang en bewaartermijnen zijn projectkeuzes. We toetsen eisen rond Europese hosting of een private opstelling voordat we een architectuur voorstellen. De vereiste controles en verantwoordelijkheden leggen we vast in de scope.'),('Bouwen jullie nog websites?','Ja. Websites, webshops en branding blijven beschikbaar. Websiteprojecten staan bij Werk, apart van de focus op AI, CRM en IT op deze homepage.')],work='Bekijk ons websitewerk',crmTitle='CRM-software op maat voor Europese organisaties',crmDesc='CRM op maat voor Europese bedrijven: klantprocessen, portalen, integraties en rapportage, afgestemd op je organisatie.',crmLead='Je CRM moet passen bij de manier waarop je organisatie werkt. We ontwerpen klantplatformen rond je teams, gegevens en commerciële processen, met een duidelijk plan voor migratie, integratie en ondersteuning.',crmSections=[('Breng de klantcyclus in kaart','Definieer aanvragen, relaties, verkoopkansen, offertes, bestellingen en overdracht samen met de betrokken teams.'),('Verbind bestaande tools','Onderzoek koppelingen met e-mail, websites, boekhouding en ERP. Bevestig API’s, rechten en synchronisatieregels vóór de bouw.'),('Ontwerp toegang en rapportage','Bepaal gebruikersrollen, klantportalen, managementoverzichten en de definities achter operationele rapporten.'),('Plan implementatie en eigendom','Leg gegevensmigratie, praktijktesten, uitrol, documentatie, broncodeafspraken en ondersteuning vast.')],crmFaq=[('Wanneer is CRM op maat zinvol?','Als bestaande tools je processen, integraties of toegangsvereisten onvoldoende ondersteunen. We vergelijken eerst de uitbreiding van je huidige software met een nieuwe toepassing.'),('Kan AI deel uitmaken van het CRM?','Ja, voor afgesproken taken zoals aanvragen structureren of antwoorden voorbereiden uit goedgekeurde informatie. Prijzen, toezeggingen en belangrijke acties kunnen menselijke goedkeuring blijven vereisen.'),('Wat kost een CRM op maat?','Scope, koppelingen, migratie, toegangsmodel en ondersteuning bepalen het voorstel. We spreken oplevering, acceptatiecriteria en terugkerende kosten vooraf af.')]),
'fr':dict(title='Systèmes IA, CRM sur mesure & IT en Europe | Marleo',desc='Systèmes IA, logiciels CRM sur mesure et ingénierie IT pour les organisations européennes. Reliez vos opérations, données et équipes avec Marleo.',kicker='INGÉNIERIE IA, CRM & IT · EUROPE',hero=['Une nouvelle étape.','Des systèmes à la hauteur.'],lead='Systèmes IA, plateformes CRM sur mesure et IT connectée pour les organisations européennes. Nous transformons vos processus complexes en logiciels utiles à vos équipes.',cta='Discuter de votre projet',secondary='Découvrir notre approche',note='D’un pilote ciblé à une mise en œuvre plus large. Périmètre, responsabilités et critères de réception définis dès le départ.',stage='Une organisation connectée',stageNote='Architecture illustrative · pas un environnement client réel',inbox='Informations métier',inputs=['Documents & demandes','Données CRM & ERP','Connaissances approuvées'],core='Marleo',coreSub='Vos processus, connectés.',review='Accès. Contrôle. Validation.',outputs=['Workflows assistés par IA','CRM & portails sur mesure','Tableaux de bord métier'],end='Équipes & outils métier',pillars='NOS RÉALISATIONS TECHNIQUES',pillarsTitle='Les systèmes de votre prochaine étape.',services=[('Systèmes IA & automatisation','Reliez les connaissances, traitez les documents et préparez des actions avec des points de contrôle clairs. Commencez par un processus et élargissez selon les résultats convenus.','ai-infrastructuur','Découvrir les systèmes IA','Documents · Connaissances · Agents de workflow'),('CRM & logiciels métier sur mesure','Rassemblez informations clients, processus commerciaux, portails et reporting dans une application conçue pour votre organisation.','solutions/custom-crm','Découvrir le CRM sur mesure','Opérations clients · Intégrations · Reporting'),('IT, cloud & sécurité','Une base pratique pour vos logiciels : gestion IT, cloud, contrôle des accès et assistance avec des responsabilités définies.','managed-it','Découvrir les services IT','Microsoft 365 · Infrastructure · Accès & continuité')],scope='PORTÉE EUROPÉENNE. LIVRAISON CLAIRE.',scopeTitle=['Conçu pour votre organisation.','Pensé dans son ensemble.'],scopeBody='Un service et une organisation regroupant plusieurs équipes ont des besoins différents. Nous définissons personnes, systèmes, périmètres de données et transmission avant de construire.',scopeItems=[('Entre équipes','Relier opérations, vente et équipes techniques autour d’un processus convenu.'),('Données & déploiement','Définir lieux de traitement, hébergement, fournisseurs et droits d’accès avant la mise en œuvre.'),('Une transmission claire','Convenir des tests, de la documentation, de la propriété et de l’assistance dans le contrat de projet.')],security='Voir sécurité & déploiement',process='NOTRE APPROCHE',processTitle='De la première question à l’usage quotidien.',steps=[('Analyser','Comprendre le processus, les outils, les données et les contraintes.'),('Concevoir','Convenir de l’architecture, du périmètre, du budget et des critères de réception.'),('Construire & tester','Livrer une application ciblée et tester des situations représentatives.'),('Exploiter & améliorer','Définir déploiement, transmission, supervision et évolutions.')],faqTitle='Questions avant un projet d’entreprise.',faq=[('Accompagnez-vous aussi les grandes organisations européennes ?','Notre démarche peut être adaptée à un service, une entreprise en croissance ou une grande organisation. L’analyse définit les parties prenantes, achats, intégrations, exigences de sécurité et responsabilités.'),('Pouvez-vous connecter notre CRM ou ERP actuel ?','Nous évaluons API, accès, qualité des données et contraintes des fournisseurs avant de proposer une connexion, une extension du processus ou un CRM sur mesure.'),('Pouvons-nous choisir le lieu de traitement des données ?','Hébergement, fournisseurs IA, accès et conservation font partie du projet. Les exigences européennes ou privées sont évaluées avant de proposer une architecture. Les contrôles et responsabilités requis sont définis dans le projet.'),('Créez-vous toujours des sites web ?','Oui. Sites web, boutiques et identité visuelle restent disponibles. Les projets web sont présentés dans Réalisations, séparément de l’IA, du CRM et de l’IT sur cet accueil.')],work='Voir les réalisations web',crmTitle='Logiciels CRM sur mesure pour les organisations européennes',crmDesc='Développement CRM sur mesure pour les entreprises européennes : opérations clients, portails, intégrations et reporting.',crmLead='Votre CRM doit refléter le fonctionnement de votre organisation. Nous concevons des plateformes autour de vos équipes, données et processus commerciaux, avec un plan de migration, intégration et assistance.',crmSections=[('Définir le cycle client','Convenir des demandes, relations, opportunités, devis, commandes et transmissions avec les équipes concernées.'),('Relier vos outils','Évaluer messagerie, sites, finance et ERP. Confirmer API, permissions et règles de synchronisation avant le développement.'),('Concevoir accès et reporting','Définir les rôles, portails clients, vues de gestion et indicateurs opérationnels.'),('Préparer déploiement et propriété','Convenir de la migration, des tests, de la documentation, du code source et de l’assistance.')],crmFaq=[('Quand choisir un CRM sur mesure ?','Lorsque les outils existants ne répondent pas raisonnablement aux processus, intégrations ou droits requis. L’analyse compare une extension de vos logiciels à une nouvelle application.'),('Le CRM peut-il inclure de l’IA ?','Oui, pour des tâches convenues comme structurer une demande ou préparer une réponse depuis des sources approuvées. Les prix, engagements et actions importantes peuvent rester soumis à validation humaine.'),('Quel est le coût d’un CRM sur mesure ?','Le périmètre, les intégrations, la migration, les accès et l’assistance déterminent la proposition. Livrables, réception et coûts récurrents sont convenus avant le développement.')])}

def homepage(lang,g):
 x=TEXT[lang];u=g['url'];e=g['E'];logo=g['LOGO']
 acts='<div class="eu-actions"><a class="btn btn-p" href="%s">%s</a><a class="btn btn-g" href="#approach">%s</a></div>'%(u(lang,'project-intake'),e(x['cta']),e(x['secondary']))
 hero='<section class="eu-hero ai-brand-hero"><div class="eu-grid" aria-hidden="true"></div><div class="wrap"><div class="eu-brand-signature" aria-hidden="true"><div class="eu-wordmark word">MARLEO</div></div><p class="eyebrow">%s</p><h1>%s<br><span class="gt">%s</span></h1><p class="lead">%s</p>%s<p class="eu-hero-note">%s</p></div></section>'%(e(x['kicker']),e(x['hero'][0]),e(x['hero'][1]),e(x['lead']),acts,e(x['note']))
 def nodes(items):return ''.join('<li><span class="eu-node-mark" aria-hidden="true"></span>'+e(s)+'</li>' for s in items)
 scene='<section class="eu-stage-section"><div class="wrap"><div class="eu-stage"><div class="eu-stage-top"><span>MARLEO / SYSTEM ENGINEERING</span><span class="eu-stage-tag">%s</span></div><div class="eu-architecture"><div class="eu-data"><p>%s</p><ul>%s</ul></div><div class="eu-core"><div class="eu-emblem">%s</div><h2>%s</h2><p>%s</p><span>%s</span></div><div class="eu-data"><p>%s</p><ul>%s</ul></div></div><p class="eu-stage-caption">%s</p></div><div class="eu-topics"><span>AI & AUTOMATION</span><span>CUSTOM CRM & SOFTWARE</span><span>IT, CLOUD & SECURITY</span></div></div></section>'%(e(x['stage']),e(x['inbox']),nodes(x['inputs']),logo,e(x['core']),e(x['coreSub']),e(x['review']),e(x['end']),nodes(x['outputs']),e(x['stageNote']))
 services='<section class="sec eu-services"><div class="wrap"><div class="sec-h"><span class="eyebrow">%s</span><h2>%s</h2></div>'%(e(x['pillars']),e(x['pillarsTitle']))
 for i,(title,body,slug,cta,tags) in enumerate(x['services']):services+='<article class="eu-service"><span class="eu-index">%02d</span><div><h3>%s</h3><p class="eu-tags">%s</p></div><div><p>%s</p><a class="eu-link" href="%s">%s<span class="marleo-mark marleo-mark--next" aria-hidden="true"></span></a></div></article>'%(i+1,e(title),e(tags),e(body),u(lang,slug),e(cta))
 services+='</div></section>'
 scope='<section class="sec eu-scope" id="europe-scope"><div class="wrap eu-scope-grid"><div><span class="eyebrow">%s</span><h2>%s<br><span>%s</span></h2><p class="lead">%s</p><a class="eu-link" href="%s">%s</a></div><div class="eu-scope-items">%s</div></div></section>'%(e(x['scope']),e(x['scopeTitle'][0]),e(x['scopeTitle'][1]),e(x['scopeBody']),u(lang,'security-deployment'),e(x['security']),''.join('<article><span>%02d</span><div><h3>%s</h3><p>%s</p></div></article>'%(i+1,e(t),e(b)) for i,(t,b) in enumerate(x['scopeItems'])))
 process='<section class="sec eu-approach" id="approach"><div class="wrap"><div class="sec-h"><span class="eyebrow">%s</span><h2>%s</h2></div><div class="eu-steps">%s</div></div></section>'%(e(x['process']),e(x['processTitle']),''.join('<article><span>%02d</span><h3>%s</h3><p>%s</p></article>'%(i+1,e(t),e(b)) for i,(t,b) in enumerate(x['steps'])))
 faq='<section class="sec eu-faq"><div class="wrap split"><div><h2>%s</h2><a class="eu-link" href="%s#website-work">%s</a></div>%s</div></section>'%(e(x['faqTitle']),u(lang,'projecten'),e(x['work']),g['faq']([{'q':q,'a':a} for q,a in x['faq']]))
 return g['page'](lang,'',x['title'],x['desc'],hero+scene+g['home_products'](lang,g)+g['system_showcase'](lang,u)+scope+process+faq+g['band'](lang))

def crm_page(lang,g):
 x=TEXT[lang];e=g['E'];u=g['url']
 body=g['phero'](lang,'solutions/custom-crm','CRM',x['crmTitle'],x['crmLead'])
 body+='<section class="sec"><div class="wrap eu-crm-sections">'+''.join('<article><span class="eu-index">%02d</span><div><h2>%s</h2><p class="lead">%s</p></div></article>'%(i+1,e(t),e(b)) for i,(t,b) in enumerate(x['crmSections']))+'</div></section>'
 body+='<section class="sec"><div class="wrap split"><h2>'+e(x['faqTitle'])+'</h2>'+g['faq']([{'q':q,'a':a} for q,a in x['crmFaq']])+'</div></section>'
 return g['page'](lang,'solutions/custom-crm',x['crmTitle']+' | Marleo',x['crmDesc'],body+g['band'](lang))
